/* The same editable outline is expanded, never a detached copy. */
let outlineZoom=1,outlineCenter={x:360,y:195},outlineExpanded=false,outlineOnlyActive=false;
function outlineFit(){outlineZoom=1;outlineCenter={x:360,y:195};refreshShape()}
function outlineZoomAt(factor,anchor=outlineCenter){const next=clamp(outlineZoom*factor,1,12),ratio=outlineZoom/next;outlineCenter={x:anchor.x+(outlineCenter.x-anchor.x)*ratio,y:anchor.y+(outlineCenter.y-anchor.y)*ratio};outlineZoom=next;refreshShape()}
function outlineExpand(){outlineExpanded=!outlineExpanded;const card=$('#outlineCard');if(card){card.classList.toggle('outline-expanded',outlineExpanded);$('#outlineExpand').textContent=outlineExpanded?'↙ Zmniejsz':'⤢ Powiększ obrys';$('#outlineSelected').hidden=!outlineExpanded;$('#shapeDrawing').focus({preventScroll:true})}document.body.classList.toggle('outline-is-expanded',outlineExpanded)}
const zoomStartDraft=startDraft;startDraft=function(){zoomStartDraft();outlineZoom=1;outlineCenter={x:360,y:195};outlineExpanded=false;document.body.classList.remove('outline-is-expanded')};
const zoomShapeSVG=shapeSVG;
shapeSVG=function(){let text=zoomShapeSVG();text=text.replace('viewBox="0 0 720 390"',`viewBox="${outlineCenter.x-360/outlineZoom} ${outlineCenter.y-195/outlineZoom} ${720/outlineZoom} ${390/outlineZoom}"`); // Keep labels and handles readable without enlarging their overlap.
const readable=Math.max(1,720/($('#shapeDrawing')?.clientWidth||720));
text=text.replace(/(font-size|stroke-width|r)="([\d.]+)"/g,(_,key,n)=>`${key}="${Number(n)*readable/outlineZoom}"`);return text};
const zoomRefreshShape=refreshShape;
refreshShape=function(){zoomRefreshShape();const svg=$('#shapeSvg');if(svg&&outlineOnlyActive)svg.querySelectorAll('[data-shape-edge]').forEach(g=>{if(+g.dataset.shapeEdge!==shapeActive){g.querySelector('text')?.setAttribute('visibility','hidden');g.querySelectorAll('path')[2]?.setAttribute('visibility','hidden')}});if($('#outlinePercent'))$('#outlinePercent').textContent=Math.round(outlineZoom*100)+'%';if($('#outlineSelectedLabel'))$('#outlineSelectedLabel').textContent='Odcinek '+edgeLetter(shapeActive)+' · mm';const input=$('#outlineLength');if(input&&input!==document.activeElement)input.value=Math.round(Geom.edge(shapeDraft,shapeActive).len*10)/10;if($('#outlineMessage'))$('#outlineMessage').textContent=$('#shapeWarning')?.textContent||''};
const zoomShapeSelect=shapeSelect;
shapeSelect=function(i,focus=false){zoomShapeSelect(i,focus&&!outlineExpanded);if(focus&&outlineExpanded){$('#outlineLength')?.focus({preventScroll:true});$('#outlineLength')?.select()}};
const zoomShapeLength=shapeLength;
shapeLength=function(i,v){zoomShapeLength(i,v);if($('#outlineMessage'))$('#outlineMessage').textContent=$('#shapeWarning')?.textContent||'';if($('#outlineLength'))$('#outlineLength').value=Math.round(Geom.edge(shapeDraft,shapeActive).len*10)/10};
const zoomRenderShape=renderShape;
renderShape=function(){zoomRenderShape();const host=$('#shapeDrawing'),card=host.parentElement;card.id='outlineCard';card.classList.add('outline-card');card.classList.toggle('outline-expanded',outlineExpanded);host.tabIndex=0;host.setAttribute('aria-label','Obrys — tło przesuwa widok, narożnik zmienia geometrię');const bar=document.createElement('div');bar.className='outline-toolbar';bar.innerHTML=`<button id="outlineExpand" onclick="outlineExpand()">${outlineExpanded?'↙ Zmniejsz':'⤢ Powiększ obrys'}</button><button aria-label="Oddal obrys" onclick="outlineZoomAt(1/1.5)">−</button><span id="outlinePercent">100%</span><button aria-label="Przybliż obrys" onclick="outlineZoomAt(1.5)">＋</button><button onclick="outlineFit()">Dopasuj</button><label><input type="checkbox" ${outlineOnlyActive?'checked':''} onchange="outlineOnlyActive=this.checked;refreshShape()">Tylko wybrany wymiar</label>`;host.before(bar);const panel=document.createElement('div');panel.id='outlineSelected';panel.hidden=!outlineExpanded;panel.innerHTML='<label id="outlineSelectedLabel" for="outlineLength"></label><input id="outlineLength" type="text" inputmode="text" data-dimension-math autocomplete="off" spellcheck="false" min="20" max="100000" step="0.1" aria-label="Długość wybranego odcinka" onchange="shapeLength(shapeActive,this.value)"><p id="outlineMessage" role="status"></p>';host.after(panel);const help=document.createElement('p');help.className='outline-help';help.textContent='Kółko / dwa palce: zoom · przeciągnij tło: przesuń widok · narożnik: edytuj · Esc: zmniejsz';card.append(help);refreshShape()};
bindShapeDrag=function(){const host=$('#shapeDrawing'),pointers=new Map();let drag=null,gesture=null;
const point=ev=>new DOMPoint(ev.clientX,ev.clientY).matrixTransform($('#shapeSvg').getScreenCTM().inverse());
const pair=()=>{const p=[...pointers.values()];return {x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2,d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}};
function cancelVertex(){if(drag?.kind==='vertex'){shapeDraft.points=drag.original;shapeFrame=null}drag=null}
host.onpointerdown=ev=>{if(ev.button!==0)return;ev.preventDefault();pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});host.setPointerCapture(ev.pointerId);if(pointers.size===2){cancelVertex();gesture=pair();refreshShape();return}if(pointers.size>2)return;const vertex=ev.target.closest('[data-vertex]'),edge=ev.target.closest('[data-shape-edge]');if(vertex){const svg=$('#shapeSvg'),i=+vertex.dataset.vertex;shapeActive=i;shapeFrame={b:Geom.bounds(shapeDraft.points),s:+svg.dataset.scale};drag={kind:'vertex',id:ev.pointerId,i,pt:point(ev),matrix:svg.getScreenCTM().inverse(),original:copy(shapeDraft.points)};refreshShape()}else if(edge){shapeSelect(+edge.dataset.shapeEdge,true);drag=null}else{host.focus({preventScroll:true});drag={kind:'pan',id:ev.pointerId,pt:point(ev),center:{...outlineCenter},matrix:$('#shapeSvg').getScreenCTM().inverse()}}};
host.onpointermove=ev=>{if(!pointers.has(ev.pointerId))return;pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});if(pointers.size===2){const next=pair();if(gesture&&gesture.d>0){const matrix=$('#shapeSvg').getScreenCTM().inverse(),before=new DOMPoint(gesture.x,gesture.y).matrixTransform(matrix),after=new DOMPoint(next.x,next.y).matrixTransform(matrix);outlineCenter.x+=before.x-after.x;outlineCenter.y+=before.y-after.y;outlineZoomAt(next.d/gesture.d,before)}gesture=next;return}if(!drag||drag.id!==ev.pointerId)return;const p=new DOMPoint(ev.clientX,ev.clientY).matrixTransform(drag.matrix);if(drag.kind==='pan'){outlineCenter={x:drag.center.x+drag.pt.x-p.x,y:drag.center.y+drag.pt.y-p.y};refreshShape()}else{const q=drag.original[drag.i];shapeDraft.points=ShapeEdit.move(drag.original,drag.i,{x:Math.round(q.x+(p.x-drag.pt.x)/shapeFrame.s),y:Math.round(q.y+(p.y-drag.pt.y)/shapeFrame.s)},shapeSnap,12/(shapeFrame.s*outlineZoom));refreshShape()}};
const end=ev=>{pointers.delete(ev.pointerId);if(drag?.id===ev.pointerId&&drag.kind==='vertex'){if(ev.type==='pointercancel'||Geom.polygonError(shapeDraft.points)){shapeDraft.points=drag.original;toast('Przywrócono narożnik — ruch anulowany lub niepoprawny obrys.')}shapeFrame=null}drag=null;gesture=null;refreshShape()};host.onpointerup=end;host.onpointercancel=end;host.onlostpointercapture=ev=>{if(pointers.has(ev.pointerId))end(ev)};
host.addEventListener('wheel',ev=>{ev.preventDefault();if(drag?.kind==='vertex')return;outlineZoomAt(Math.exp(-ev.deltaY*.0015),point(ev))},{passive:false});host.onkeydown=ev=>{if(ev.target!==host)return;if(['+','=','-','Home','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Escape'].includes(ev.key))ev.preventDefault();if(ev.key==='+'||ev.key==='=')outlineZoomAt(1.5);if(ev.key==='-')outlineZoomAt(1/1.5);if(ev.key==='Home')outlineFit();if(ev.key==='Escape'&&outlineExpanded)outlineExpand();const d=40/outlineZoom;if(ev.key==='ArrowLeft')outlineCenter.x-=d;if(ev.key==='ArrowRight')outlineCenter.x+=d;if(ev.key==='ArrowUp')outlineCenter.y-=d;if(ev.key==='ArrowDown')outlineCenter.y+=d;if(ev.key.startsWith('Arrow'))refreshShape()};
};
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&outlineExpanded){ev.preventDefault();outlineExpand()}});
